<?php require_once __DIR__.'/config/db.php'; $pageTitle='Shop'; $cat=(int)($_GET['category']??0);$q=trim((string)($_GET['q']??''));$cats=$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();$st=$pdo->prepare('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE (:c=0 OR p.category_id=:c2) AND (p.name LIKE :q OR p.description LIKE :q2) ORDER BY p.name');$st->execute(['c'=>$cat,'c2'=>$cat,'q'=>"%$q%",'q2'=>"%$q%"]);$products=$st->fetchAll();require __DIR__.'/includes/header.php'; ?>
<div class="container section-space"><p class="eyebrow">Find your favorite</p><h1 class="display-5 mb-4">Shop all</h1><form class="panel row g-2 mb-4" method="get"><div class="col-md-5"><label class="form-label" for="q">Search</label><input class="form-control" id="q" name="q" value="<?=e($q)?>"></div><div class="col-md-4"><label class="form-label" for="category">Category</label><select class="form-select" name="category" id="category"><option value="0">All categories</option><?php foreach($cats as $c): ?><option value="<?=$c['id']?>" <?=$cat===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach; ?></select></div><div class="col-md-3 d-grid align-self-end"><button class="btn btn-dark">Filter</button></div></form><p class="meta"><?=count($products)?> products</p><div class="row g-3"><?php foreach($products as $i=>$p): ?><div class="col-6 col-lg-3"><article class="product-card"><div class="product-art"><div class="shape <?= $i%3===1?'circle':($i%3===2?'book':'') ?>" style="--art:<?=['#b9c4ad','#c88c6e','#9db6c0'][$i%3]?>"></div></div><div class="product-body"><div class="meta"><?=e($p['category_name'])?> · <?=$p['stock_quantity']?> in stock</div><div class="d-flex justify-content-between gap-2"><h3><?=e($p['name'])?></h3><b class="small"><?=money($p['base_price'])?></b></div><p class="small text-secondary"><?=e($p['description'])?></p><button class="btn btn-outline-dark btn-sm rounded-pill w-100" data-add="<?=$p['id']?>" <?=$p['stock_quantity']<1?'disabled':''?>>Add to bag</button></div></article></div><?php endforeach; ?></div></div><?php require __DIR__.'/includes/footer.php'; ?>